mkdir -p lib test && cat > package.json <<'EOF'
{
  "name": "set-proto",
  "version": "0.1.0",
  "description": "Cross-platform helper to set the prototype of an object at runtime",
  "main": "lib/index.js",
  "types": "lib/index.d.ts",
  "files": [
    "lib"
  ],
  "scripts": {
    "test": "node --test test/"
  },
  "keywords": [
    "prototype",
    "setPrototypeOf",
    "__proto__",
    "polyfill"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=0.10"
  }
}
EOF
cat > lib/index.js <<'EOF'
'use strict';

/**
 * Set the prototype of `obj` to `proto` and return `obj`.
 *
 * Uses the native Object.setPrototypeOf when available, falls back to the
 * `__proto__` setter, and finally to copying `proto`'s own properties onto
 * `obj` for engines that support neither.
 */
var setPrototypeOf = Object.setPrototypeOf ||
  ({ __proto__: [] } instanceof Array ? setProtoOf : mixinProperties);

function setProtoOf(obj, proto) {
  obj.__proto__ = proto;
  return obj;
}

function mixinProperties(obj, proto) {
  for (var prop in proto) {
    if (!Object.prototype.hasOwnProperty.call(obj, prop)) {
      obj[prop] = proto[prop];
    }
  }
  return obj;
}

module.exports = setPrototypeOf;
module.exports.setProtoOf = setProtoOf;
module.exports.mixinProperties = mixinProperties;
EOF
cat > lib/index.d.ts <<'EOF'
declare function setPrototypeOf<T extends object>(obj: T, proto: object | null): T;

declare namespace setPrototypeOf {
  function setProtoOf<T extends object>(obj: T, proto: object | null): T;
  function mixinProperties<T extends object>(obj: T, proto: object | null): T;
}

export = setPrototypeOf;
EOF
cat > test/index.test.js <<'EOF'
'use strict';

const test = require('node:test');
const assert = require('node:assert');
const setPrototypeOf = require('..');

const strategies = {
  default: setPrototypeOf,
  setProtoOf: setPrototypeOf.setProtoOf,
};

for (const [name, fn] of Object.entries(strategies)) {
  test(`${name}: sets the prototype and returns the object`, () => {
    const proto = { greet() { return 'hi'; } };
    const obj = {};
    assert.strictEqual(fn(obj, proto), obj);
    assert.strictEqual(Object.getPrototypeOf(obj), proto);
    assert.strictEqual(obj.greet(), 'hi');
  });

  test(`${name}: supports a null prototype`, () => {
    const obj = fn({}, null);
    assert.strictEqual(Object.getPrototypeOf(obj), null);
  });
}

test('default uses native Object.setPrototypeOf when available', () => {
  assert.strictEqual(setPrototypeOf, Object.setPrototypeOf);
});

test('mixinProperties copies properties without overwriting own ones', () => {
  const obj = { a: 1 };
  const result = setPrototypeOf.mixinProperties(obj, { a: 2, b: 3 });
  assert.strictEqual(result, obj);
  assert.deepStrictEqual(obj, { a: 1, b: 3 });
});
EOF
cat > .gitignore <<'EOF'
node_modules/
*.log
EOF
cat > README.md <<'EOF'
# set-proto

Cross-platform way to set the prototype of an object at runtime.

```js
const setPrototypeOf = require('set-proto');

const obj = setPrototypeOf({}, { greet() { return 'hi'; } });
obj.greet(); // 'hi'
```

Strategy, in order of preference:

1. Native `Object.setPrototypeOf` (ES2015+)
2. The `__proto__` setter
3. Copying the prototype's enumerable properties onto the object. This is a
   last resort for very old engines, and `Object.getPrototypeOf` will not
   reflect the change.

The individual strategies are exported as `setProtoOf` and `mixinProperties`.

## Development

```sh
npm test
```
EOF
npm test 2>&1 | tail -12

